"""Derive SkyyHud/build_skyyhud_0.3.36.py from the LIVE SkyyHud 0.3.35 (build_skyyhud_0.3.35.py = the tools/deploy_set.py SET pin, generated by
tools/hud_0_3_35_patch.py - never edit a generated script, edit this patch). Every anchor is asserted; at the end every change is undone on a
copy and compared with 0.3.35 (nothing else changed; tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/hud_0_3_36_patch.py   then   python SkyyHud/build_skyyhud_0.3.36.py   (never --deploy)
Check: python SkyyHud/test_skyyhud_0.3.36.py [--dir <folder inside tools/dev/scratch/>] [--keep]
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.3.36 (2026-10-24) = HUD FARMING LINE = CROP FARMING LEVEL (docs/answered/skills.md 2026-10-24 FARMING TREE LEVEL: Skyy picked "Crop
Farming level (Recommended)"; SkyyTrees 0.6.3 uses crop Farming). Skyy: "because of farming not tracking my collection from the harvester i
wasnt getting xp either, so im 20 lvls behind on farming. according to the tree. but my harvester says lvl 8" + "and my skills say lvl 16".
  1. The Skills widget's Farming line shows the CROP Farming level (skill:<uuid> entry "Farming") as its number - no more skill:farmavg:<uuid>
     (the average of Farming / Ranching / Orchard, e.g. "5 (F 16 / R 1 / O 0)"). The HUD reads skill:farmavg nowhere any more.
  2. Ranching and Orchard stay visible: they have their own Skills lines since 0.3.24 (bits 11 / 12, Settings > HUD > Skills). Each one
     whose OWN line is off is shown in a bracket after the Farming level: "16 (R 1 / O 0)"; switch the Ranching / Orchard line on and it
     leaves the bracket (both on = plain "16"). A skill SkyySkills does not publish ("-") is left out of the bracket. No saved-data change:
     the mask decides it, so the shape never flaps; the 1 s fill sets the value text as before.
  Unchanged: every other widget and line, layouts / masks / file format, commands, permissions, config rows, bridge keys published.
  ROLLBACK to 0.3.35: safe, no data step (the Farming line shows the average again).
'''

P = G.Patch(os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.35.py"), os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.36.py"))
assert P.has('VERSION = "0.3.35"\n') and P.has("GENERATED by tools/hud_0_3_35_patch.py from the LIVE 0.3.34"), "not the generated SkyyHud 0.3.35 script"
SYS0, CMD0 = P.s.count("registerSystem("), P.s.count("registerCommand(")

# ================================================================================================ docstring + version
P.rep('''"""SkyyHud 0.3.35 - build script (javassist via jpype). GENERATED by tools/hud_0_3_35_patch.py from the LIVE 0.3.34 - edit the patch.
Run:   python build_skyyhud_0.3.35.py            -> SkyyHud/SkyyHud-0.3.35.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.35.py
''', '''"""SkyyHud 0.3.36 - build script (javassist via jpype). GENERATED by tools/hud_0_3_36_patch.py from the LIVE 0.3.35 - edit the patch.
Run:   python build_skyyhud_0.3.36.py            -> SkyyHud/SkyyHud-0.3.36.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.36.py
''' + NOTE + '''0.3.35 (generated by tools/hud_0_3_35_patch.py from 0.3.34):
''')
P.rep('VERSION = "0.3.35"\n', 'VERSION = "0.3.36"\n')

# ================================================================================================ the line bits Ranching / Orchard
P.rep('''assert SKL_FARM_K == 4 and SKILL_LINES[10:] == ["Fishing", "Ranching", "Orchard"]
''', '''assert SKL_FARM_K == 4 and SKILL_LINES[10:] == ["Fishing", "Ranching", "Orchard"]
SKL_RANCH_BIT, SKL_ORCH_BIT = 1 << SKILL_LINES.index("Ranching"), 1 << SKILL_LINES.index("Orchard")   # 0.3.36: their own lines (bracket rule)
assert (SKL_RANCH_BIT, SKL_ORCH_BIT) == (2048, 4096)
''')

# ================================================================================================ farmVal: crop Farming + the bracket
P.rep('''# 0.3.24: the Farming line's text - "12 (F 15 / R 9 / O 12)" from skill:farmavg:<uuid> (SkyySkills 0.4.37+, Integer floor of the three's
# average) + the three entries of skill:<uuid>; without the key (older SkyySkills) the plain Farming level as before. Memory reads only.
wid.addMethod(CtNewMethod.make("""
public static String farmVal(java.util.Map b, String meS, String[] parts) {
  long fa = lnum(bstr(b, "skill:farmavg:" + meS), -1L);
  if (fa < 0L) return skillVal(parts, "Farming");
  return fa + " (F " + skillVal(parts, "Farming") + " / R " + skillVal(parts, "Ranching") + " / O " + skillVal(parts, "Orchard") + ")";
}""", wid))''', '''# 0.3.36 (Skyy picked "Crop Farming level (Recommended)", docs/answered/skills.md 2026-10-24): the Farming line's number = the CROP Farming
# level (skill:<uuid> entry "Farming"), never the skill:farmavg average. Ranching / Orchard whose own line is OFF in the shown mask follow in a
# bracket - "16 (R 1 / O 0)" - so they stay visible; a skill not published ("-") is left out; both lines on = the plain level. Memory reads only.
wid.addMethod(CtNewMethod.make("""
public static String farmVal(String[] parts, int vis) {
  String f = skillVal(parts, "Farming");
  String x = "";
  if ((vis & @RB@) == 0) {
    String r = skillVal(parts, "Ranching");
    if (!"-".equals(r)) x = "R " + r;
  }
  if ((vis & @OB@) == 0) {
    String o = skillVal(parts, "Orchard");
    if (!"-".equals(o)) x = x.length() == 0 ? "O " + o : x + " / O " + o;
  }
  return x.length() == 0 ? f : f + " (" + x + ")";
}""".replace("@RB@", str(SKL_RANCH_BIT)).replace("@OB@", str(SKL_ORCH_BIT)), wid))''')
P.rep('''    }} else if (k == {SKL_FARM_K}) val = farmVal(b, meS, parts);   // 0.3.24: the Farming average + F / R / O''',
      '''    }} else if (k == {SKL_FARM_K}) val = farmVal(parts, vis);   // 0.3.36: crop Farming + the Ranching / Orchard not shown on their own line''')
P.rep('''SKL_FARM_K = SKILL_LINES.index("Farming")          # 0.3.24: the line that shows the Farming average (skill:farmavg:<uuid>)''',
      '''SKL_FARM_K = SKILL_LINES.index("Farming")          # 0.3.24 / 0.3.36: the line that shows crop Farming (+ the R / O bracket)''')

# ================================================================================================ checks on the result
assert '"skill:farmavg' not in P.s, "0.3.36: nothing in the code reads skill:farmavg any more"
assert P.s.count("registerSystem(") == SYS0 and P.s.count("registerCommand(") == CMD0, "0.3.36 adds no system / command"
P.finish()
